insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 11, 'E ele lhes respondeu: Qual de vós será a pessoa que, caso tenha uma ovelha, e se a tal cair em uma cova no sábado, não usará de sua força para a levantar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 12, 'Ora, quanto mais vale um ser humano que uma ovelha! Assim, pois, é lícito fazer o bem nos sábados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 13, 'Então disse para aquele homem: Estende a tua mão. Ele a estendeu, e foi-lhe restaurada, sã como a outra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 14, 'Então os fariseus saíram e se reuniram para planejar contra ele, como o matariam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 15, 'Mas Jesus, sabendo disso, retirou-se dali. Muitas multidões o seguiram, e ele curou a todos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 16, 'E ele lhes ordenava que não o tornassem conhecido;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 17, 'Para que se cumprisse o que foi dito pelo profeta Isaías:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 18, 'Eis aqui meu servo a quem escolhi, meu amado em quem minha alma se agrada; sobre ele porei o meu Espírito, e ele anunciará justiça às nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 19, 'Ele não fará brigas, nem gritará; ninguém ouvirá pelas ruas a sua voz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 20, 'A cana rachada ele não quebrará, o pavio que fumega ele não apagará, até que conduza a justiça à vitória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 21, 'E em seu nome as nações terão esperança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 22, 'Então lhe trouxeram um endemoninhado cego e mudo; e ele o curou de tal maneira que o cego e mudo passou a falar e a ver.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 23, 'E todas as multidões se admiravam e diziam: Não é este o Filho de Davi?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 24, 'Mas quando os fariseus ouviam isso, diziam: Ele não expulsa os demônios, a não ser por Belzebu, o chefe dos demônios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 25, 'Porém Jesus, entendendo os pensamentos deles, disse-lhes: Todo reino dividido contra si mesmo é destruído; e toda cidade ou casa dividida contra si mesma não permanecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 26, 'Ora, se Satanás expulsa a Satanás, contra si mesmo está dividido; como, pois, permanecerá o seu reino?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 27, 'E se eu expulso os demônios por Belzebu, então por quem vossos filhos os expulsam? Portanto, eles mesmos serão vossos juízes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 28, 'Mas se eu pelo Espírito de Deus expulso os demônios, logo o Reino de Deus já chegou sobre vos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 29, 'Ou como pode alguém entrar na casa do valente, e saquear seus bens, sem primeiro amarrar ao valente? Depois disso saqueará sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 30, 'Quem não é comigo é contra mim; e quem não ajunta comigo, espalha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 31, 'Por isso eu vos digo: todo pecado e blasfêmia serão perdoados aos seres humanos; mas a blasfêmia contra o Espírito não será perdoada aos seres humanos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 32, 'E qualquer um que falar palavra contra o Filho do homem lhe será perdoado; mas qualquer um que falar contra o Espírito Santo, não lhe será perdoado, nem na era presente, nem na futura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 33, 'Ou fazei a árvore boa, e seu fruto bom; ou fazei a árvore má, e seu fruto mau; pois pelo fruto se conhece a árvore.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 34, 'Ninhada de víboras, como podeis vós falar boas coisas, sendo maus? Pois a boca fala do que o coração tem em abundância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 35, 'A pessoa boa tira coisas boas do bom tesouro do coração, e a pessoa má tira coisas más do tesouro mau.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 36, 'Eu, porém, vos digo que de toda palavra imprudente que as pessoas falarem, dela prestarão contas no dia do juízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 37, 'Porque por tuas palavras serás justificado, e por tuas palavras serás condenado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 38, 'Então responderam uns dos escribas e dos fariseus, dizendo: Mestre, queremos ver de ti algum sinal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 39, 'Mas ele lhes deu a seguinte resposta: Uma geração má e adúltera pede sinal; mas não lhe será dado, exceto o sinal do profeta Jonas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 40, 'Porque assim como Jonas esteve três dias e três noites no ventre da baleia, assim também o Filho do homem estará três dias e três noites no coração da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 41, 'Os de Nínive se levantarão no Juízo com esta geração, e a condenarão; porque se arrependeram com a pregação de Jonas. E eis aqui quem é maior que Jonas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 42, 'A rainha do sul se levantará no Juízo com esta geração, e a condenará; porque veio dos confins da terra para ouvir a sabedoria de Salomão. E eis aqui quem é maior que Salomão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 43, 'Quando o espírito imundo sai de alguém, anda por lugares secos buscando repouso, e não o acha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 44, 'Então diz: ‘Voltarei para a minha casa, de onde saí.’ E quando chega, a encontra desocupada, varrida, e arrumada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 45, 'Então vai, e toma consigo outros sete espíritos piores que ele; eles entram, e moram ali; e a última [condição] de tal pessoa se torna pior que a primeira. Assim também acontecerá com esta geração má.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 46, 'Enquanto ele ainda estava falando às multidões, eis que sua mãe e seus irmãos estavam fora, querendo falar com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 47, 'E alguém lhe disse: Eis que tua mãe e teus irmãos estão fora, querendo falar contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 48, 'Porém ele disse em resposta ao que o avisou: Quem é minha mãe? E quem são meus irmãos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 49, 'Então estendeu sua mão para os seus discípulos, e disse: Eis aqui minha mãe e meus irmãos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 12, 50, 'Pois qualquer um que fizer a vontade do meu Pai, que está nos céus, esse é meu irmão, e irmã, e mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 1, 'Naquele dia, Jesus saiu de casa e se sentou junto ao mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 2, 'E ajuntaram-se perto dele tantas multidões, de maneira que ele entrou num barco e se sentou; e toda a multidão ficou na praia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 3, 'E ele lhes falou muitas coisas por parábolas. Ele disse: Eis que o semeador saiu a semear.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 4, 'E enquanto semeava, caiu parte [das sementes] junto ao caminho, e vieram as aves e a comeram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 5, 'E outra [parte] caiu entre pedras, onde não havia muita terra, e logo nasceu, porque não tinha terra funda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 6, 'Mas quando o sol surgiu, queimou-se; e por não ter raiz, secou-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 7, 'E outra [parte] caiu entre espinhos, e os espinhos cresceram e a sufocaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 8, 'E outra [parte] caiu em boa terra, e rendeu fruto: um a cem, outro a sessenta, e outro a trinta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 9, 'Quem tem ouvidos para ouvir, ouça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 10, 'Então os discípulos se aproximaram, e lhe perguntaram: Por que falas a eles por parábolas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 11, 'E ele lhes respondeu: Porque a vós é dado saber os mistérios do Reino dos céus, mas a eles não é dado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 12, 'Pois a quem tem, lhe será dado, e terá em abundância; mas a quem não tem, até aquilo que tem lhe será tirado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 13, 'Por isso falo a eles por parábolas; porque vendo, não veem; e ouvindo, não ouvem, nem entendem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 14, 'Assim neles se cumpre a profecia de Isaías, que diz: De fato ouvireis, mas não entendereis; De fato vereis, mas não percebereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 15, 'Porque o coração deste povo está insensível; Com seus ouvidos dificilmente ouvem, e seus olhos fecharam; A fim de não haver que seus olhos vejam, seus ouvidos ouçam, Seus corações entendam, e se arrependam, E eu os cure.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 16, 'Mas benditos são os vossos olhos, porque veem; e os vossos ouvidos, porque ouvem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 17, 'Pois em verdade vos digo que muitos profetas e justos desejaram ver o que vós vedes, mas não viram; e [desejaram] ouvir o que vós ouvis, mas não ouviram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 18, 'Portanto, ouvi vós a parábola do semeador:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 19, 'Quando alguém ouve a palavra do Reino e não a entende, o maligno vem e arranca o que foi semeado em seu coração; este é o que foi semeado junto ao caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 20, 'E o que foi semeado entre as pedras é o que ouve a palavra, e logo a recebe com alegria,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 21, 'mas não tem raiz em si mesmo. Em vez disso, dura um pouco, mas quando vem a aflição ou a perseguição pela palavra, logo tropeça na fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 22, 'E o que foi semeado entre os espinhos é o que ouve a palavra, mas a ansiedade com o tempo presente e a sedução das riquezas sufocam a palavra, e fica sem dar fruto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 23, 'Mas o que foi semeado em boa terra, este é o que ouve e entende a palavra, e o que dá e produz fruto, um a cem, outro a sessenta, e outro a trinta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 24, 'E ele lhes declarou outra parábola, dizendo: O Reino dos céus é semelhante a um homem que semeia boa semente em seu campo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 25, 'Mas, enquanto as pessoas dormiam, o inimigo dele veio, semeou joio entre o trigo, e foi embora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 26, 'E, quando a erva cresceu e produziu fruto, então apareceu também o joio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 27, 'Então os servos do dono da propriedade chegaram, e lhe perguntaram: “Senhor, não semeaste boa semente no teu campo? De onde, pois, veio o joio?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 28, 'E ele lhes respondeu: “Um inimigo fez isto”. Em seguida, os servos lhe perguntaram: “Queres, pois, que vamos e o tiremos?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 29, 'Ele, porém, lhes respondeu: “Não, para não haver que, enquanto tirais o joio, arranqueis com ele também o trigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 30, 'Deixai-os crescer ambos juntos até a colheita; e no tempo da colheita direi aos que colhem: ‘Recolhei primeiro o joio, e amarrai-o em molhos, para o queimarem; mas ao trigo ajuntai no meu celeiro’.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 31, 'Ele lhes propôs outra parábola: O Reino dos céus é semelhante a um grão de mostarda que alguém tomou e semeou no seu campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 32, 'De fato, dentre todas as sementes, esta é a menor. Mas quando cresce, é a maior das hortaliças; e se torna [tamanha] árvore, que as aves do céu vêm e se aninham em seus ramos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 33, 'Ele lhes disse outra parábola: O Reino dos céus é semelhante ao fermento que uma mulher tomou e misturou em três medidas de farinha, até que tudo ficasse fermentado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 34, 'Tudo isto Jesus falou por parábolas às multidões. Sem parábolas ele não lhes falava,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 35, 'para que se cumprisse o que foi falado pelo profeta, que disse: Abrirei a minha boca em parábolas; Pronunciarei coisas escondidas desde a fundação do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 36, 'Então Jesus despediu as multidões, e foi para casa. Seus discípulos se aproximaram dele, e disseram: Explica-nos a parábola do joio do campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 37, 'E ele lhes respondeu: O que semeia a boa semente é o Filho do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 38, 'E o campo é o mundo; e a boa semente, estes são os filhos do Reino; e o joio são os filhos do maligno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 39, 'E o inimigo, que o semeou, é o diabo; e a colheita é o fim da era; e os que colhem são os anjos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 40, 'Portanto, como o joio é colhido e queimado no fogo, assim também será no fim desta era.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 41, 'O Filho do homem enviará seus anjos, e eles recolherão do seu Reino todas as causas do pecado, assim como os que praticam injustiça,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 42, 'e os lançarão na fornalha de fogo. Ali haverá choro e ranger de dentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 43, 'Então os justos brilharão como o sol, no Reino de seu Pai. Quem tem ouvidos para ouvir, ouça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 44, 'O Reino dos céus também é semelhante a um tesouro escondido num campo, que um homem, depois de achá-lo, escondeu. Então, em sua alegria, vai, vende tudo quanto tem, e compra aquele campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 45, 'O Reino dos céus também é semelhante a um homem negociante, que buscava boas pérolas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 46, 'Quando este achou uma pérola de grande valor, foi, vendeu tudo quanto tinha, e a comprou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 47, 'O Reino dos céus também é semelhante a uma rede lançada ao mar, que colhe toda espécie [de peixes] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 48, 'E quando está cheia, [os pescadores] puxam-na à praia, sentam-se, e recolhem os bons em cestos, mas os ruins lançam fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 49, 'Assim será ao fim da era; os anjos sairão, e separarão dentre os justos os maus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 50, 'e os lançarão na fornalha de fogo. Ali haverá choro e ranger de dentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 51, 'E Jesus lhes perguntou: Entendestes todas estas coisas?Eles lhe responderam: Sim, Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 52, 'E ele lhes disse: Portanto todo escriba que se tornou discípulo no Reino dos céus é semelhante a um chefe de casa, que do seu tesouro tira coisas novas e velhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 53, 'E aconteceu que, quando Jesus acabou essas parábolas, retirou-se dali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 54, 'E vindo à sua terra, ensinava-os na sinagoga deles, de tal maneira que ficavam admirados, e diziam: De onde [vêm] a este tal sabedoria, e os milagres?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 55, 'Não é este o filho do carpinteiro? E não se chama sua mãe Maria, e seus irmãos Tiago, José, Simão, e Judas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 56, 'Não estão todas as suas irmãs conosco? Ora, de onde [vem] a este tudo isto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 57, 'E ofenderam-se por causa dele. Mas Jesus lhes disse: Não há profeta sem honra, a não ser em sua terra, e em sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 13, 58, 'E não fez ali muitos milagres por causa da incredulidade deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 1, 'Naquele tempo Herodes, o tetrarca, ouviu relato a respeito de Jesus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 2, 'e disse aos seus servos: Este é João Batista; ele ressuscitou dos mortos, e por isso os milagres operam nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 3, 'Porque Herodes havia prendido a João, acorrentado-o, e posto na prisão, por causa de Herodias, mulher do seu irmão Filipe;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 4, 'pois João lhe dizia: Não te lícito que a tenhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 5, '[Herodes] queria matá-lo, mas tinha medo do povo, pois o consideravam profeta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 6, 'Porém, enquanto era celebrado o aniversário de Herodes, a filha de Herodias dançou no meio [das pessoas] , e agradou a Herodes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 7, 'Por isso prometeu a ela dar tudo o que pedisse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 8, 'E ela, tendo sido induzida por sua mãe, disse: Dá-me aqui num prato a cabeça de João Batista.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 9, 'E o rei se entristeceu; mas devido ao juramento, e aos que estavam presentes, ordenou que isso fosse concedido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 10, 'Então mandou degolarem João na prisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 11, 'Sua cabeça foi trazida num prato, e dada à garota, e ela a levou à sua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 12, 'E seus discípulos vieram, tomaram o corpo, e o enterraram; e foram avisar a Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 13, 'Depois de Jesus ouvir, retirou-se dali num barco, a um lugar deserto, sozinho; mas assim que as multidões ouviram acerca disso, seguiram-no a pé das cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 14, 'Quando Jesus saiu, viu uma grande multidão. Ele se compadeceu deles, e curou dentre eles os enfermos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 15, 'E chegando o entardecer, os seus discípulos se aproximaram dele, e disseram: O lugar é deserto, e já é tarde. Despede as multidões, para irem às aldeias, e comprarem para si de comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 16, 'Mas Jesus lhes respondeu: Eles não precisam ir. Vós mesmos, dai-lhes de comer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 17, 'E eles lhe disseram: Nada temos aqui além de cinco pães e dois peixes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 18, 'Então disse: Trazei-os aqui a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 19, 'Ele mandou às multidões que se sentassem sobre a grama. Então tomou os cinco pães e os dois peixes, levantou os olhos ao céu, e [os] abençoou. Em seguida partiu os pães, deu-os aos discípulos, e os discípulos às multidões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 20, 'E todos comeram, e se fartaram. E do que sobrou dos pedaços levantaram doze cestos cheios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 21, 'E os que comeram foram quase cinco mil homens, sem contar as mulheres e as crianças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 22, 'E logo Jesus mandou os seus discípulos entrarem no barco, e que fossem adiante dele para a outra margem, enquanto ele despedia as multidões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 23, 'Depois de despedir as multidões, subiu ao monte, à parte, para orar. Tendo chegado a noite, ele estava ali sozinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 24, 'E o barco já estava no meio do mar, atormentado pelas ondas, porque o vento era contrário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 25, 'Mas à quarta vigília da noite Jesus foi até eles, andando sobre o mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 26, 'Quando os discípulos o viram andar sobre o mar, apavoraram-se, dizendo: É um fantasma! E gritaram de medo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 27, 'Mas Jesus logo lhes falou, dizendo: Tende coragem! Sou eu, não tenhais medo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 28, 'E Pedro lhe respondeu, dizendo: Senhor, se és tu, manda-me vir a ti sobre as águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 29, 'E ele disse: Vem. Então Pedro desceu do barco e andou sobre as águas, para vir em direção a Jesus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 30, 'Mas quando viu o vento forte, teve medo; e começando a afundar, gritou: Senhor, salva-me!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 31, 'Imediatamente Jesus estendeu a mão, segurou-o, e disse-lhe: [Homem] de pouca fé, por que duvidaste?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 32, 'E quando subiram no barco, o vento se aquietou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 33, 'Então os que estavam no barco vieram e o adoraram, dizendo: Verdadeiramente tu és o Filho de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 34, 'E havendo passado para a outra margem, chegaram à terra de Genesaré.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 35, 'E quando os homens daquele lugar o reconheceram, deram aviso por toda aquela região em redor, e lhe trouxeram todos os que estavam enfermos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 14, 36, 'E rogavam-lhe que tão somente tocassem a borda de sua roupa; e todos os que tocavam ficaram curados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 1, 'Então [alguns] escribas e fariseus de Jerusalém se aproximaram de Jesus, e perguntaram:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 2, 'Por que os teus discípulos transgridem a tradição dos anciãos? Pois não lavam suas mãos quando comem pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 3, 'Porém ele lhes respondeu: E vós, por que transgredis o mandamento de Deus por vossa tradição?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 4, 'Pois Deus mandou, dizendo: Honra ao teu pai e à [tua] mãe; e quem maldisser ao pai ou à mãe seja sentenciado à morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 5, 'Mas vós dizeis: “Qualquer um que disser ao pai ou à mãe: ‘Todo o proveito que terias de mim é oferta exclusiva [para Deus] ’, não [precisa] honrar seu pai ou à sua mãe”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 6, 'E [assim] invalidastes o mandamento de Deus por vossa tradição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 7, 'Hipócritas! Isaías bem profetizou sobre vós, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 8, 'Este povo com sua boca se aproxima de mim, e com os lábios me honra; mas o seu coração está longe de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 9, 'Em vão, porém, me veneram, ensinando doutrinas que são regras humanas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 10, 'Assim chamou a multidão para si, e disse-lhes: Ouvi e entendei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 11, 'Não é o que entra na boca que contamina o ser humano; mas sim o que sai da boca, isso contamina o ser humano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 12, 'Então os seus discípulos aproximaram-se dele, e lhe perguntaram: Tu sabes que os fariseus se ofenderam quando ouviram essa palavra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 13, 'Mas ele respondeu: Toda planta que meu Pai celestial não plantou será arrancada pela raiz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 14, 'Deixai-os, são guias cegos de cegos. E se o cego guiar [outro] cego, ambos cairão na cova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 15, 'E Pedro lhe disse: Explica-nos esta parábola.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 16, 'Porém Jesus disse: Até vós ainda estais sem entender?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 17, 'Não percebeis ainda que tudo o que entra na boca vai ao ventre, mas [depois] é lançado na privada?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 18, 'Porém as coisas que saem da boca procedem do coração; e elas contaminam o ser humano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 19, 'Pois do coração procedem maus pensamentos, mortes, adultérios, pecados sexuais, furtos, falsos testemunhos, blasfêmias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 20, 'Estas coisas são as que contaminam o ser humano; mas comer sem lavar as mãos não contamina o ser humano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 21, 'E, tendo Jesus partido dali, foi para as partes de Tiro e de Sidom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 22, 'E eis que uma mulher Cananeia, que tinha saído daquela região, clamou-lhe: Senhor, Filho de Davi, tem misericórdia de mim! Minha filha está miseravelmente endemoninhada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 23, 'Mas ele não lhe respondeu palavra. Então seus discípulos se aproximaram dele, e rogaram-lhe, dizendo: Manda-a embora, porque ela está gritando atrás de nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 24, 'E ele respondeu: Não fui enviado para ninguém além das ovelhas perdidas da casa de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 25, 'Então ela veio e se prostrou diante dele, dizendo: Senhor, socorre-me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 26, 'Mas ele respondeu: Não é bom tomar o pão dos filhos e lançá-lo aos cachorrinhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 27, 'Ela, porém, disse: Sim, Senhor. Porém os cachorrinhos também comem, das migalhas que caem da mesa dos seus senhores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 28, 'Então Jesus lhe respondeu: Ó mulher, grande [é] a tua fé. A ti seja feito como tu queres. E desde aquela hora sua filha ficou curada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 29, 'E tendo Jesus partido dali, veio ao mar da Galileia. Ele subiu a um monte, e ali se sentou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 30, 'E vieram a ele muitas multidões, que tinham consigo mancos, cegos, mudos, aleijados, e muitos outros; e os lançaram aos pés de Jesus, e ele os curou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 31, 'Desta maneira, as multidões se maravilhavam quando viam os mudos falarem, os aleijados ficarem sãos, os mancos andarem, e os cegos verem; então glorificaram ao Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 32, 'Jesus chamou a si os seus discípulos, e disse: Estou compadecido com a multidão, porque já há três dias que estão comigo, e não têm o que comer. E não quero os deixar ir em jejum, para que não desmaiem no caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 33, 'E os seus discípulos lhe responderam: De onde conseguiremos tantos pães no deserto, para saciar tão grande multidão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 34, 'Jesus lhes perguntou: Quantos pães tendes? E eles disseram: Sete; e uns poucos peixinhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 35, 'Então mandou as multidões que se sentassem pelo chão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 36, 'Tomou os sete pães e os peixes, deu graças e os partiu. Em seguida, ele os deu aos seus discípulos, e os discípulos à multidão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 37, 'E todos comeram e se saciaram; e levantaram dos pedaços que sobraram sete cestos cheios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 38, 'E foram os que comeram quatro mil homens, sem contar as mulheres e as crianças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 15, 39, 'Depois de despedir as multidões, [Jesus] entrou em um barco, e veio à região de Magdala.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 1, 'Então os fariseus e os saduceus se aproximaram dele e, a fim de tentá-lo, pediram-lhe que lhes mostrasse algum sinal do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 2, 'Mas ele lhes respondeu: Quando chega a tarde, dizeis: “ [Haverá] tempo bom, pois o céu está vermelho”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 3, 'E pela manhã: “Hoje [haverá] tempestade, pois o céu está de um vermelho sombrio”. Hipócritas! Vós bem sabeis distinguir a aparência do céu, mas os sinais dos tempos não podeis?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 4, 'Uma geração má e adúltera pede um sinal; mas nenhum sinal lhe será dado, a não ser o sinal do profeta Jonas. Então os deixou, e foi embora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 5, 'E quando os seus discípulos vieram para a outra margem, esqueceram-se de tomar pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 6, 'E Jesus lhes disse: Ficai atentos, e tende cuidado com o fermento dos fariseus e saduceus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 7, 'E eles argumentaram entre si, dizendo: É porque não tomamos pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 8, 'Jesus percebeu, e disse-lhes: Por que estais argumentando entre vós mesmos, ó [homens] de pouca fé, que não tomastes pão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 9, 'Ainda não entendeis, nem vos lembrais dos cinco pães dos cinco mil, e quantos cestos levantastes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 10, 'Nem dos sete pães dos quatro mil, e quantos cestos levantastes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 11, 'Como não entendeis que não foi pelo pão que eu vos disse para tomardes cuidado com o fermento dos fariseus e saduceus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 12, 'Então entenderam que ele não havia dito que tomassem cuidado com o fermento de pão, mas sim, com a doutrina dos fariseus e saduceus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 13, 'E tendo Jesus vindo às partes da Cesareia de Filipe, perguntou aos seus discípulos: Quem as pessoas dizem que eu, o Filho do homem, sou?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 14, 'E eles responderam: Alguns João Batista, outros Elias, e outros Jeremias ou algum dos profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 15, 'Ele lhes disse: E vós, quem dizeis que eu sou?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 16, 'E Simão Pedro respondeu: Tu és o Cristo, o Filho do Deus vivo!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 17, 'E Jesus lhe replicou: Bendito és tu, Simão, filho de Jonas; pois não foi carne e sangue que o revelou a ti, mas sim meu Pai, que [está] nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 18, 'E eu também te digo que tu és Pedro, e sobre esta pedra edificarei a minha igreja; e as portas do Xeol não prevalecerão contra ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 19, 'E a ti darei as chaves do Reino dos céus; e tudo o que ligares na terra terá sido ligado nos céus; e tudo o que desligares na terra terá sido desligado nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 20, 'Então mandou aos seus discípulos que a ninguém dissessem que ele era Jesus, o Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 21, 'Desde então Jesus começou a mostrar a seus discípulos que ele tinha que ir a Jerusalém, e sofrer muito pelos anciãos, pelos chefes dos sacerdotes, e pelos escribas, e ser morto, e ser ressuscitado ao terceiro dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 22, 'E Pedro o tomou à parte, e começou a repreendê-lo, dizendo: Misericórdia de ti, Senhor! De maneira nenhuma isso te aconteça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 23, 'Mas ele se virou, e disse a Pedro: Para trás de mim, Satanás! Tu és um meio de tropeço, porque não compreendes as coisas de Deus, mas sim as humanas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 24, 'Então Jesus disse a seus discípulos: Se alguém quiser vir após mim, negue-se a si mesmo, tome sobre si a sua cruz, e siga-me.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 25, 'Pois qualquer um que quiser salvar a sua vida a perderá; porém qualquer um que por causa de mim perder a sua vida, [este] a achará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 26, 'Pois que proveito há para alguém, se ganhar o mundo todo, mas perder a sua alma? Ou que dará alguém em resgate da sua alma?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 27, 'Pois o Filho do homem virá na glória do seu Pai com os seus anjos, e então recompensará a cada um segundo as suas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 16, 28, 'Em verdade vos digo, que há alguns, dos que aqui estão, que não experimentarão a morte, até que vejam o Filho do homem vir em seu Reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 1, 'Seis dias depois, Jesus tomou consigo Pedro, Tiago, e seu irmão João, e os levou a sós a um monte alto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 2, 'Então transfigurou-se diante deles; seu rosto brilhou como o sol, e suas roupas se tornaram brancas como a luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 3, 'E eis que lhes apareceram Moisés e Elias, falando com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 4, 'Pedro, então, disse a Jesus: Senhor, bom é para nós estarmos aqui. Se queres, façamos aqui três tendas: uma para ti, uma para Moisés, e uma para Elias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 5, 'Enquanto ele ainda estava falando, eis que uma nuvem brilhante os cobriu. E eis que uma voz da nuvem disse: Este é o meu Filho amado, em quem me agrado; a ele ouvi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 6, 'Quando os discípulos ouviram, caíram sobre seus rostos, e tiveram muito medo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 7, 'Jesus se aproximou deles, tocou-os, e disse: Levantai-vos, e não tenhais medo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 8, 'E quando eles levantaram seus olhos, não viram a ninguém, a não ser a Jesus somente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 9, 'E enquanto desciam do monte, Jesus lhes disse a seguinte ordem: Não conteis a visão a ninguém, até que o Filho do homem seja ressuscitado dos mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 10, 'E os seus discípulos lhe perguntaram: Por que, então, os escribas dizem que Elias tem que vir primeiro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 11, 'Jesus lhes respondeu: Em verdade Elias virá primeiro, e restaurará todas as coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 12, 'Digo-vos, porém, que Elias já veio, mas não o reconheceram. Em vez disso fizeram dele tudo o que quiseram. Assim também o Filho do homem sofrerá por meio deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 13, 'Então os discípulos entenderam que ele lhes falara a respeito de João Batista.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 14, 'E quando chegaram à multidão, veio a ele um homem, que se ajoelhou diante dele, e disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 15, 'Senhor, tem misericórdia do meu filho, que é epilético, e sofre muito mal; porque cai muitas vezes no fogo, e muitas vezes na água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 16, 'E eu o trouxe aos teus discípulos, mas não o puderam curar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 17, 'Jesus respondeu: Ó geração incrédula e perversa! Até quando estarei convosco? Até quando vos suportarei? Trazei-o a mim aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 18, 'E Jesus o repreendeu. Então o demônio saiu dele, e o menino sarou desde aquela hora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 19, 'Depois os discípulos se aproximaram de Jesus em particular, e perguntaram: Por que nós não o pudemos expulsar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 20, 'E Jesus lhes respondeu: Por causa da vossa incredulidade; pois em verdade vos digo, que se tivésseis fé como um grão de mostarda, diríeis a este monte: “Passa-te daqui para lá”, E ele passaria. E nada vos seria impossível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 21, 'Mas este tipo [de demônio] não sai, a não ser por oração e jejum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 22, 'E enquanto eles estavam na Galileia, Jesus lhes disse: O Filho do homem será entregue em mãos de homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 23, 'E o matarão, e ele será ressuscitado ao terceiro dia.E eles se entristeceram muito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 24, 'E quando entraram em Cafarnaum, os cobradores da taxa de duas dracmas vieram a Pedro, e perguntaram: Vosso mestre não paga as duas dracmas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 25, 'Ele respondeu: Sim. Quando ele entrou em casa, Jesus o antecipou, dizendo: Que te parece, Simão? De quem os reis da terra cobram tributos ou taxas? Dos seus filhos, ou dos outros?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 26, 'Pedro lhe respondeu: Dos outros. Jesus lhe disse: Logo, os filhos são livres de pagar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 17, 27, 'Mas para não os ofendermos, vai ao mar, e lança o anzol. Toma o primeiro peixe que subir, e quando lhe abrir a boca, acharás uma moeda de quatro dracmas. Toma-a, e dá a eles por mim e por ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 1, 'Naquela hora os discípulos se aproximaram de Jesus, e perguntaram: Ora, quem é o maior no Reino dos céus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 2, 'Então Jesus chamou a si uma criança, e a pôs no meio deles,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 3, 'e disse: Em verdade vos digo, que se vós não converterdes, e fordes como crianças, de maneira nenhuma entrareis no Reino dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 4, 'Assim, qualquer um que for humilde como esta criança, este é o maior no reino dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 5, 'E qualquer um que receber a uma criança como esta em meu nome, recebe a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 6, 'Mas qualquer um que conduzir ao pecado a um destes pequeninos que creem em mim, melhor lhe fora que uma grande pedra de moinho lhe fosse pendurada ao pescoço, e se afundasse no fundo do mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 7, 'Ai do mundo por causa das tentações do pecado! Pois é necessário que as tentações venham, mas ai daquela pessoa por quem a tentação vem!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 8, 'Portanto, se a tua mão ou o teu pé te faz pecar, corta-os, e lança-os de ti; melhor te é entrar manco ou aleijado na vida do que, tendo duas mãos ou dois pés, ser lançado no fogo eterno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 9, 'E se o teu olho te faz pecar, arranca-o, e lança-o de ti. Melhor te é entrar com um olho na vida do que, tendo dois olhos, ser lançado no inferno de fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 10, 'Olhai para que não desprezeis a algum destes pequeninos; porque eu vos digo que os seus anjos nos céus sempre veem a face do meu Pai, que [está] nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 11, 'Pois o Filho do homem veio para salvar o que havia se perdido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 12, 'Que vos parece? Se alguém tivesse cem ovelhas, e uma delas se desviasse, por acaso não iria ele pelos montes, deixando as noventa e nove, em busca da desviada?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 13, 'E se acontecesse de achá-la, em verdade vos digo que ele se alegra mais daquela, do que das noventa e nove que se não desviaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 14, 'Da mesma maneira, não é da vontade do vosso Pai, que [está] nos céus, que um sequer destes pequeninos se perca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 15, 'Porém, se teu irmão pecar contra ti, vai repreendê-lo entre ti e ele só; se te ouvir, ganhaste o teu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 16, 'Mas se não ouvir, toma ainda contigo um ou dois, para que toda palavra se confirme pela boca de duas ou três testemunhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 17, 'E se não lhes der ouvidos, comunica à igreja; e se também não der ouvidos à igreja, considera-o como gentio e publicano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 18, 'Em verdade vos digo que tudo o que vós ligardes na terra será ligado no céu; e tudo o que desligardes na terra será desligado no céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 19, 'E digo-vos também que, se dois de vós concordarem na terra acerca de qualquer coisa que pedirem, isso lhes será feito por meu Pai, que [está] nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 20, 'Pois onde dois ou três estiverem reunidos em meu nome, ali eu estou no meio deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 21, 'Então Pedro aproximou-se dele, e perguntou: Senhor, até quantas vezes meu irmão pecará contra mim, e eu lhe perdoarei? Até sete?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 22, 'Jesus lhe respondeu: Eu não te digo até sete, mas sim até setenta vezes sete.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 23, 'Por isso o Reino dos céus é comparável a um certo rei, que quis fazer acerto de contas com os seus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 24, 'E começando a fazer acerto de contas, foi-lhe apresentado um que lhe devia dez mil talentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 25, 'Como ele não tinha com que pagar, o seu senhor mandou que ele, sua mulher, filhos, e tudo quanto tinha fossem vendidos para se fazer o pagamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 26, 'Então aquele servo caiu e ficou prostrado diante dele, dizendo: “Senhor, tem paciência comigo, e tudo te pagarei”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 27, 'O senhor daquele servo compadeceu-se dele, então o soltou e lhe perdoou a dívida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 28, 'Todavia, depois daquele servo sair, achou um companheiro de serviço seu, que lhe devia cem denários; então o agarrou e o sufocou, dizendo: “Paga-me o que [me] deves!”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 29, 'Então o seu colega se prostrou diante dos seus pés, e lhe suplicou, dizendo: “Tem paciência comigo, e tudo te pagarei”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 30, 'Mas ele não quis. Em vez disso foi lançá-lo na prisão até que pagasse a dívida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 31, 'Quando os seus companheiros de serviço viram o que se passava, entristeceram-se muito. Então vieram denunciar ao seu senhor tudo o que havia se passado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 32, 'Assim o seu senhor o chamou, e lhe disse: “Servo mau! Toda aquela dívida te perdoei, porque me suplicaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 33, 'Não tinhas tu a obrigação de ter tido misericórdia do sevo colega teu, assim como eu tive misericórdia de ti?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 34, 'E, enfurecido, o seu senhor o entregou aos torturadores até que pagasse tudo o que lhe devia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 18, 35, 'Assim também meu Pai celestial vos fará, se não perdoardes de coração cada um ao seu irmão suas ofensas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 1, 'E aconteceu que, quando Jesus acabou essas palavras, partiu da Galileia, e veio para a região da Judeia, além do Jordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 2, 'E muitas multidões o seguiram, e ele os curou ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 3, 'Então os fariseus se aproximaram dele e, provando-o, perguntaram-lhe: É lícito ao homem se divorciar da sua mulher por qualquer causa?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 4, 'Porém ele lhes respondeu: Não tendes lido que aquele que [os] fez no princípio, macho e fêmea os fez,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 5, 'e disse: Portanto o homem deixará pai e mãe, e se unirá a sua mulher, e os dois serão uma única carne?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 6, 'Assim eles já não são mais dois, mas sim uma única carne; portanto, o que Deus juntou, o ser humano não separe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 7, 'Eles lhe disseram: Por que, pois, Moisés mandou [lhe] dar carta de separação, e divorciar-se dela?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 8, '[Jesus] lhes disse: Por causa da dureza dos vossos corações Moisés vos permitiu divorciardes de vossas mulheres; mas no princípio não foi assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 9, 'Porém eu vos digo que qualquer um que se divorciar de sua mulher, a não ser por causa de pecado sexual, e se casar com outra, adultera; e o que se casar com a divorciada [também] adultera.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 10, 'Os seus discípulos lhe disseram: Se assim é a condição do homem com a mulher, não convém se casar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 11, 'Porém ele lhes disse: Nem todos recebem esta palavra, a não ser aqueles a quem é dado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 12, 'Pois há castrados que nasceram assim do ventre da mãe; e há castrados que foram castrados pelos homens; e há castrados que castraram a si mesmos por causa do Reino dos céus. Quem pode receber [isto] ,receba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 13, 'Então lhe trouxeram crianças, para que pusesse as mãos sobre elas e orasse, mas os discípulos os repreendiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 14, 'Mas Jesus disse: Deixai as crianças, e não as impeçais de vir a mim, porque delas é o Reino dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 15, 'Ele pôs as mãos sobre elas, e depois partiu-se dali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 16, 'E eis que alguém se aproximou, e perguntou-lhe: “Bom Mestre, que bem farei para eu ter a vida eterna?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 17, 'E ele lhe disse: “Por que me chamas bom? Ninguém há bom, a não ser um: Deus. Porém, se queres entrar na vida, guarda os mandamentos.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 18, 'Perguntou-lhe ele: “Quais?” E Jesus respondeu: “Não cometerás homicídio, não adulterarás, não furtarás, não darás falso testemunho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 19, 'honra ao teu pai e à [tua] mãe; e amarás ao teu próximo como a ti mesmo.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 20, 'O rapaz lhe disse: “Tenho guardado tudo isso desde a minha juventude. Que me falta ainda?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 21, 'Disse-lhe Jesus: “Se queres ser completo, vai, vende o que tens, e dá aos pobres. Assim terás um tesouro no céu. Então vem, segue-me.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 22, 'Mas quando o rapaz ouviu essa palavra, foi embora triste, porque tinha muitos bens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 23, 'Jesus, então, disse aos seus discípulos: “Em verdade vos digo que dificilmente um rico entrará no reino dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 24, 'Aliás, eu vos digo que é mais fácil um camelo passar pela abertura de uma agulha do que o rico entrar no reino de Deus.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 25, 'Quando os seus discípulos ouviram [isso] , espantaram-se muito, e disseram: “Quem, pois, pode se salvar?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 26, 'Jesus olhou [para eles] ,e lhes respondeu: Para os seres humanos, isto é impossível; mas para Deus tudo é possível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 27, 'Então Pedro se pôs a falar, e lhe perguntou: Eis que deixamos tudo, e te seguimos; o que, pois, conseguiremos ter?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 28, 'E Jesus lhes disse: Em verdade vos digo que vós que me seguistes, na regeneração, quando o Filho do homem se sentar no trono de sua glória, vós também vos sentareis sobre doze tronos, para julgar as doze tribos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 29, 'E qualquer um que houver deixado casas, ou irmãos, ou irmãs, ou pai, ou mãe, ou mulher, ou filhos, ou terras por causa do meu nome, receberá cem vezes tanto, e herdará a vida eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 19, 30, 'Porém muitos primeiros serão últimos; e últimos, primeiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 1, 'Pois o reino dos céus é semelhante a um homem, dono de propriedade, que saiu de madrugada para empregar trabalhadores para a sua vinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 2, 'Ele entrou em acordo com os trabalhadores por um denário ao dia, e os mandou à sua vinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 3, 'E quando saiu perto da hora terceira, viu outros que estavam desocupados na praça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 4, 'Então disse-lhes: “Ide vós também à vinha, e vos darei o que for justo”. E eles foram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 5, 'Saindo novamente perto da hora sexta e nona, fez o mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 6, 'E quando saiu perto da décima primeira hora, achou outros que estavam desocupados, e lhes perguntou: “Por que estais aqui o dia todo desocupados?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 7, 'Eles lhe disseram: “Porque ninguém nos empregou”. Ele lhes respondeu: “Ide vós também à vinha, e recebereis o que for justo”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 8, 'E chegando o anoitecer, o senhor da vinha disse ao seu mordomo: “Chama aos trabalhadores, e paga-lhes o salário, começando dos últimos, até os primeiros”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 9, 'Então vieram os de cerca da hora décima primeira, e receberam um denário cada um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 10, 'Quando os primeiros vieram, pensavam que receberiam mais; porém eles também receberam um denário cada um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 11, 'Assim, ao receberem, murmuraram contra o chefe de casa,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 12, 'dizendo: “Estes últimos trabalharam uma única hora, e tu os igualaste conosco, que suportamos a carga e o calor do dia”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 13, 'Ele, porém, respondeu a um deles: “Amigo, nada de errado estou fazendo contigo. Não concordaste tu comigo por um denário?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 14, 'Toma o que é teu, e vai embora; e quero dar a este último tanto quanto a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 15, 'Acaso não me é lícito fazer do que é meu o que eu quiser? Ou o teu olho é mau, porque eu sou bom?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 16, 'Assim os últimos serão primeiros; e os primeiros, últimos; pois muitos são chamados, mas poucos escolhidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 17, 'E enquanto Jesus subia a Jerusalém, tomou consigo os doze discípulos à parte no caminho, e lhes disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 18, 'Eis que estamos subindo a Jerusalém, e o Filho do homem será entregue aos chefes dos sacerdotes e aos escribas, e o condenarão à morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 19, 'E o entregarão aos gentios, para que dele escarneçam, e o açoitem, e crucifiquem; mas ao terceiro dia ressuscitará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 20, 'Então se aproximou dele a mãe dos filhos de Zebedeu, com os seus filhos. Ela o adorou para lhe pedir algo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 21, 'E ele lhe perguntou: O que queres? Ela lhe disse: Dá ordem para que estes meus dois filhos se sentem, um à tua direita e outro à tua esquerda, no teu Reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 22, 'Porém Jesus respondeu: Não sabeis o que pedis. Podeis vós beber o cálice que eu beberei, e ser batizados com o batismo com que eu sou batizado? Eles lhe disseram: Podemos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 23, 'E ele lhes disse: De fato meu cálice bebereis, e com o batismo com que eu sou batizado sereis batizados; mas sentar-se à minha direita, e à minha esquerda, não me cabe concedê-lo, mas [será] para os que por meu Pai está preparado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 24, 'E quando os dez ouviram [isso] ,indignaram-se contra os dois irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 25, 'Então Jesus os chamou a si, e disse: Vós bem sabeis que os chefes dos gentios os dominam, e os grandes usam de autoridade sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 26, 'Mas não será assim entre vós. Ao contrário, quem quiser se tornar grande entre vós seja o vosso assistente;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 27, 'e quem quiser ser o primeiro entre vós seja o vosso servo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 28, 'assim como o Filho do homem não veio para ser servido, mas sim para servir, e para dar a sua vida em resgate por muitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 29, 'Quando eles saíram de Jericó, uma grande multidão o seguiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 30, 'E eis que dois cegos assentados junto ao caminho, ao ouvirem que Jesus passava, clamaram: Senhor, Filho de Davi, tem misericórdia de nós!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 31, 'E a multidão os repreendia, para que se calassem, mas eles clamavam ainda mais: Senhor, Filho de Davi, tem misericórdia de nós!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 32, 'Então Jesus parou, chamou-os, e perguntou: Que quereis que eu vos faça?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 33, 'Eles lhe responderam: Senhor, que nossos olhos sejam abertos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 20, 34, 'E Jesus, compadecido deles, tocou-lhes os olhos. E logo os olhos deles enxergaram, e o seguiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 1, 'E quando se aproximaram de Jerusalém, e chegaram a Betfagé, ao monte das Oliveiras, então Jesus mandou dois discípulos, dizendo-lhes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 2, 'Ide à aldeia em vossa frente, e logo achareis uma jumenta amarrada, e um jumentinho com ela; desamarra-a, e trazei-os a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 3, 'E se alguém vos disser algo, direis: “O Senhor precisa deles, mas logo os devolverá”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 4, 'Ora, tudo isto aconteceu para que se cumprisse o que foi dito pelo profeta, que disse:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 5, 'Dizei à filha de Sião: “Eis que o teu rei vem a ti, manso, e sentado sobre um jumento; um jumentinho, filho de uma animal de carga”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 6, 'Os discípulos foram, e fizeram como Jesus havia lhes mandado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 7, 'Então trouxeram a jumenta e o jumentinho, puseram as suas capas sobre eles, e fizeram [-no] montar sobre elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 8, 'E uma grande multidão estendia suas roupas pelo caminho, e outros cortavam ramos das árvores, e os espalhavam pelo caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 9, 'E as multidões que iam adiante, e as que seguiam, clamavam: Hosana ao Filho de Davi! Bendito o que vem no nome do Senhor! Hosana nas alturas!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 10, 'Enquanto ele entrava em Jerusalém, toda a cidade se alvoroçou, perguntando: Quem é este?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 11, 'E as multidões respondiam: Este é Jesus, o Profeta de Nazaré de Galileia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 12, 'Jesus entrou no Templo de Deus; então expulsou todos os que estavam vendendo e comprando no Templo, e virou as mesas dos cambistas e as cadeiras dos que vendiam pombas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 13, 'E disse-lhes: Está escrito: “Minha casa será chamada casa de oração”; mas vós a tornastes em covil de ladrões!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 14, 'E cegos e mancos vieram a ele no Templo, e ele os curou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 15, 'Quando os chefes dos sacerdotes e os escribas viram as maravilhas que ele fazia, e as crianças gritando no Templo: “Hosana ao Filho de Davi!”, eles ficaram indignados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 16, 'E perguntaram-lhe: Ouves o que estas [crianças] dizem? E Jesus lhes respondeu: Sim. Nunca lestes: “Da boca das crianças e dos bebês providenciaste o louvor?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 17, 'Então ele os deixou, e saiu da cidade para Betânia, e ali passou a noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 18, 'E pela manhã, enquanto voltava para a cidade, teve fome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 19, 'Quando ele viu uma figueira perto do caminho, veio a ela, mas nada nela achou, a não ser somente folhas. E disse-lhe: Nunca de ti nasça fruto, jamais!E imediatamente a figueira se secou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 20, 'Os discípulos viram, e ficaram maravilhados, dizendo: Como a figueira se secou de imediato?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 21, 'Porém Jesus lhes respondeu: Em verdade vos digo: se tiverdes fé, e não duvidardes, vós não somente fareis isto à figueira, mas até se disserdes a este monte: “Levanta-te, e lança-te no mar”, isso se fará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 22, 'E tudo o que pedirdes em oração, crendo, recebereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 23, 'Depois de entrar no templo, quando ele estava ensinando, os chefes dos sacerdotes e os anciãos do povo se aproximaram dele, perguntando: Com que autoridade fazes isto? E quem te deu esta autoridade?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 24, 'Jesus lhes respondeu: Eu também vos farei uma pergunta. Se vós a responderdes a mim, também eu vos responderei com que autoridade faço isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 25, 'De onde era o batismo de João? Do céu, ou dos seres humanos?E eles pensaram entre si mesmos, dizendo: Se dissermos: “Do céu”, ele nos dirá: “Por que, então, não crestes nele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 26, 'Mas se dissermos: “Dos seres humanos”, temos medo da multidão, pois todos consideram João como profeta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 27, 'Então responderam a Jesus: Não sabemos. E ele lhes disse: Nem eu vos digo com que autoridade faço isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 28, 'Mas que vos parece? Um homem tinha dois filhos. Aproximando-se do primeiro, disse: “Filho, vai hoje trabalhar na minha vinha.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 29, 'Porém ele respondeu: “Não quero”; mas depois se arrependeu, e foi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 30, 'E, aproximando-se do segundo, disse da mesma maneira. E ele respondeu: “Eu [vou] , senhor”, mas não foi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 31, 'Qual dos dois fez a vontade do pai? Eles lhe responderam: O primeiro. Jesus lhes disse: Em verdade vos digo que os publicanos e as prostitutas estão indo adiante de vós ao Reino de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 32, 'Pois João veio a vós mesmos no caminho de justiça, mas não crestes nele; enquanto que os publicanos e as prostitutas nele creram. Vós, porém, mesmo tendo visto [isto] , nem assim vos arrependestes, a fim de nele crer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 33, 'Ouvi outra parábola. Havia um homem, dono de uma propriedade. Ele plantou uma vinha, cercou-a, fundou nela uma prensa de uvas, e construiu uma torre. Depois a arrendou a uns lavradores, e partiu-se para um lugar distante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 34, 'Quando chegou o tempo dos frutos, enviou seus servos aos lavradores, para receberem os frutos que a ele pertenciam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 35, 'Mas os lavradores tomaram os seus servos, e feriram um, mataram outro, e apedrejaram outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 36, 'Outra vez enviou outros servos, em maior número que os primeiros, mas fizeram-lhes o mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 37, 'E por último lhes enviou o seu filho, dizendo: “Respeitarão ao meu filho”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 38, 'Mas quando os lavradores viram o filho, disseram entre si: “Este é o herdeiro. Venhamos matá-lo, e tomemos a sua herança”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 39, 'Então o agarraram, lançaram-no para fora da vinha, e o mataram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 40, 'Ora, quando o senhor da vinha chegar, o que fará com aqueles lavradores?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 41, 'Eles lhe responderam: Aos maus dará uma morte má, e arrendará a vinha a outros lavradores, que lhe deem os frutos em seus tempos [de colheita] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 42, 'Jesus lhes disse: Nunca lestes nas Escrituras: “A pedra que os construtores rejeitaram, essa se tornou cabeça da esquina. Isto foi feito pelo Senhor, e é maravilhoso aos nossos olhos”?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 43, 'Portanto eu vos digo que o reino de Deus será tirado de vós, e será dado a um povo que produza os frutos dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 44, 'E quem cair sobre esta pedra será quebrado; mas sobre quem ela cair, ela o tornará em pó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 45, 'Quando os chefes dos sacerdotes e os fariseus ouviram estas suas parábolas, entenderam que [Jesus] estava falando deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 21, 46, 'E procuravam prendê-lo, mas temeram as multidões, pois elas o consideravam profeta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 1, 'Então Jesus voltou a lhes falar por parábolas, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 2, 'O reino dos céus é semelhante a um rei que fez uma festa de casamento para o seu filho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 3, 'e mandou a seus servos que chamassem os convidados para a festa de casamento, mas não quiseram vir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 4, 'Outra vez ele mandou outros servos, dizendo: “Dizei aos convidados: ‘Eis que já preparei meu jantar: meus bois e animais cevados já foram mortos, e tudo está pronto. Vinde à festa de casamento’”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 5, 'Porém eles não deram importância e foram embora, um ao seu campo, e outro ao seu comércio;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 6, 'e outros agarraram os servos dele, e os humilharam e os mataram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 7, 'Quando o rei Então enviou os seus exércitos, destruiu aqueles homicidas, e incendiou a cidade deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 8, 'Em seguida, disse aos seus servos: “Certamente a festa de casamento está pronta, porém os convidados não eram dignos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 9, 'Ide, pois, às saídas dos caminhos, e convidai à festa de casamento tantos quantos achardes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 10, 'Aqueles servos saíram pelos caminhos, e ajuntaram todos quantos acharam, tanto maus como bons; e a festa de casamento se encheu de convidados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 11, 'Mas quando o rei entrou para ver os convidados, percebeu ali um homem que não estava vestido com roupa adequada para a festa de casamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 12, 'Então lhe perguntou: “Amigo, como entraste aqui sem ter roupa para a festa?” E ele emudeceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 13, 'Então o rei disse aos servos: “Amarrai-o nos pés e nas mãos, tomai-o, e lançai-o nas trevas de fora. Ali haverá pranto e o ranger de dentes”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 14, 'Pois muitos são chamados, porém poucos escolhidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 15, 'Então os fariseus foram embora, e se reuniram para tramar como o apanhariam em cilada por algo que dissesse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 16, 'Depois lhe enviaram seus discípulos, juntamente com os apoiadores de Herodes, e perguntaram: Mestre, bem sabemos que tu és verdadeiro, e que com verdade ensinas o caminho de Deus, e que não te importas com a opinião de ninguém, porque não dás atenção à aparência humana.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 17, 'Dize-nos, pois, o que te parece: é lícito dar tributo a César, ou não?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 18, 'Mas Jesus, entendendo a sua malícia, disse: Por que me tentais, hipócritas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 19, 'Mostrai-me a moeda do tributo.E eles lhe trouxeram um denário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 20, 'E ele lhes perguntou: De quem é esta imagem, e a inscrição?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 21, 'Eles lhe responderam: De César. Então ele lhes disse: Dai, pois, a César o que é de César, e a Deus o que é de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 22, 'Quando ouviram isso, eles ficaram admirados; então o deixaram e se retiraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 23, 'Naquele mesmo dia chegaram a ele os saduceus, que dizem não haver ressurreição, e perguntaram-lhe,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 24, 'dizendo: Mestre, Moisés disse: Se um homem morrer sem ter filhos, seu irmão se casará com sua mulher, e gerará descendência ao seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 25, 'Ora, havia entre nós sete irmãos. O primeiro se casou, e depois morreu; e sem ter tido filhos, deixou sua mulher ao seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 26, 'E da mesma maneira também foi com o segundo, o terceiro, até os sete.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 27, 'Por último, depois de todos, a mulher também morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 28, 'Assim, na ressurreição, a mulher será de qual dos sete? Pois todos a tiveram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 29, 'Jesus, porém, lhes respondeu: Errais, por não conhecerdes as Escrituras, nem o poder de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 30, 'Porque na ressurreição, nem se tomam, nem se dão em casamento; mas são como os anjos de Deus no céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 31, 'E sobre a ressurreição dos mortos, não lestes o que Deus vos falou:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 32, 'Eu sou o Deus de Abraão, o Deus de Isaque, e o Deus de Jacó? Deus não é Deus dos mortos, mas sim dos vivos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 33, 'Quando as multidões ouviram [isto] ,ficaram admiradas de sua doutrina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 34, 'E os fariseus, ao ouvirem que ele havia feito os saduceus se calarem, reuniram-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 35, 'E um deles, especialista da Lei, tentando-o, perguntou-lhe:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 36, 'Mestre, qual é o grande mandamento na Lei?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 37, 'E Jesus lhe respondeu: Amarás ao Senhor teu Deus com todo o teu coração, com toda a tua alma, e com todo o teu entendimento:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 38, 'este é o primeiro e grande mandamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 39, 'E o segundo, semelhante a este, [é] : Amarás o teu próximo como a ti mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 40, 'Destes dois mandamentos dependem toda a Lei e os Profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 41, 'E, estando os fariseus reunidos, Jesus lhes perguntou,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 42, 'dizendo: Que pensais vós acerca do Cristo? De quem ele é filho? Eles lhe responderam: De Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 43, '[Jesus] lhes disse: Como, pois, Davi, em espírito, o chama Senhor, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 44, 'Disse o Senhor a meu Senhor: “Senta-te à minha direita, até que eu ponha os teus inimigos como estrado de teus pés”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 45, 'Ora, se Davi o chama Senhor, como é seu filho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 22, 46, 'E ninguém podia lhe responder palavra; nem ninguém ousou desde aquele dia a mais lhe perguntar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 1, 'Então Jesus falou às multidões e aos seus discípulos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 2, 'dizendo: Os escribas e os fariseus se sentam sobre o assento de Moisés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 3, 'Portanto, tudo o que eles vos disserem que guardeis, guardai, e fazei. Mas não façais segundo as suas obras, porque eles dizem e não fazem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 4, 'Pois eles amarram cargas pesadas e difíceis de levar, e as põem sobre os ombros das pessoas; porém eles nem sequer com o seu dedo as querem mover.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 5, 'E fazem todas as suas obras a fim de serem vistos pelas pessoas: por isso alargam seus filactérios, ) e fazem compridas as franjas de suas roupas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 6, 'Eles amam os primeiros assentos nas ceias, as primeiras cadeiras nas sinagogas,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 7, 'as saudações nas praças, e serem chamados: “Rabi, Rabi” pelas pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 8, 'Mas vós, não sejais chamados Rabi, porque o vosso Mestre é um: o Cristo; e todos vós sois irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 9, 'E não chameis a ninguém na terra vosso pai; porque o vosso Pai é um: aquele que está nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 10, 'Nem sejais chamados mestres; porque o vosso mestre é um: o Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 11, 'Porém o maior de vós será vosso servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 12, 'E o que a si mesmo se exaltar será humilhado; e o que a si mesmo se humilhar será exaltado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 13, 'Mas ai de vós, escribas e fariseus, hipócritas! Porque fechais o Reino dos céus em frente das pessoas; pois nem vós entrais, nem permitis a entrada do que estão para entrar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 14, 'Ai de vós, escribas e fariseus, hipócritas! Porque devorais as casas das viúvas, e [isso] com pretexto de longas orações; por isso recebereis mais grave condenação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 15, 'Ai de vós, escribas e fariseus, hipócritas! Porque rodeais o mar e a terra para fazerdes um prosélito; e quando é feito, vós o tornais filho do inferno duas vezes mais que a vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 16, 'Ai de vós, guias cegos, que dizeis: “Qualquer um que jurar pelo templo, nada é; mas qualquer um que jurar pelo ouro do templo, devedor é”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 17, 'Tolos e cegos! Pois qual é maior: o ouro, ou o templo que santifica o ouro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 18, 'Também [dizeis] : “Qualquer um que jurar pelo altar, nada é; mas quem jurar pela oferta que [está] sobre ele, devedor é”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 19, 'Tolos e cegos! Pois qual é maior: a oferta, ou o altar que santifica a oferta?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 20, 'Portanto, quem jurar pelo altar, jura por ele, e por tudo o que está sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 21, 'E quem jurar pelo templo, jura por ele, e por aquele que nele habita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 22, 'E quem jurar pelo Céu, jura pelo trono de Deus, e por aquele que sobre ele está sentado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 23, 'Ai de vós, escribas e fariseus, hipócritas! Porque dais o dízimo da hortelã, do endro, e do cominho, e desprezais o que é mais importante da Lei: a justiça, a misericórdia, e a fidelidade; estas coisas devem ser feitas, sem se desprezar as outras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 24, 'Guias cegos, que coais um mosquito, e engolis um camelo!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 25, 'Ai de vós, escribas e fariseus, hipócritas! Porque limpais o exterior do copo ou do prato, mas por dentro estão cheios de extorsão e cobiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 26, 'Fariseu cego! Limpa primeiro o interior do copo e do prato, para que também o exterior deles fique limpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 27, 'Ai de vós, escribas e fariseus, hipócritas! Porque sois semelhantes aos sepulcros caiados, que por fora realmente parecem belos, mas por dentro estão cheios de ossos de cadáveres, e de toda imundícia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 28, 'Assim também vós, por fora, realmente pareceis justos às pessoas, mas por dentro estais cheios de hipocrisia e de injustiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 29, 'Ai de vós, escribas e fariseus, hipócritas! Porque edificais os sepulcros dos profetas, adornais os monumentos dos justos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 30, 'e dizeis: “Se estivéssemos nos dias dos nossos pais, nunca teríamos sido cúmplices deles quando derramaram o sangue dos profetas”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 31, 'Assim vós mesmos dais testemunho de que sois filhos dos que mataram os profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 32, 'Completai, pois, a medida de vossos pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 33, 'Serpentes, ninhada de víboras! Como escapareis da condenação do inferno?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 34, 'Por isso, eis que eu vos envio profetas, sábios, e escribas; a uns deles matareis e crucificareis, e a [outros] deles açoitareis em vossas sinagogas, e perseguireis de cidade em cidade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 35, 'para que venha sobre vós todo o sangue justo que foi derramado sobre a terra, desde o sangue do justo Abel, até o sangue de Zacarias, filho de Baraquias, ao qual matastes entre o templo e o altar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 36, 'Em verdade vos digo que tudo isto virá sobre esta geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 37, 'Jerusalém, Jerusalém, que matas os profetas, e apedrejas os que te são enviados! Quantas vezes eu quis ajuntar os teus filhos, como a galinha ajunta os seus pintos debaixo das asas; porém não quisestes!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 38, 'Eis que vossa casa vos será deixada desolada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 23, 39, 'Pois eu vos digo que a partir de agora não me vereis, até que digais: “Bendito aquele que vem no nome do Senhor”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 1, 'Jesus saiu do templo, e se foi. Então seus discípulos se aproximaram dele para lhe mostrarem os edifícios do complexo do templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 2, 'Mas Jesus lhes disse: Não vedes tudo isto? Em verdade vos digo, que não será deixada aqui pedra sobre pedra, que não seja derrubada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 3, 'E, depois de se assentar no monte das Oliveiras, os discípulos se aproximaram dele reservadamente, perguntando: Dize-nos, quando serão estas coisas, e que sinal haverá da tua vinda, e do fim da era?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 4, 'E Jesus lhes respondeu: Permanecei atentos, para que ninguém vos engane.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 5, 'Porque muitos virão em meu nome, dizendo: “Eu sou o Cristo”, e enganarão a muitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 6, 'E ouvireis de guerras, e de rumores de guerras. Olhai que não vos espanteis; porque é necessário, que tudo [isto] aconteça, mas ainda não é o fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 7, 'Pois se levantará nação contra nação, e reino contra reino; e haverá fomes, pestilências, e terremotos em diversos lugares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 8, 'Mas todas estas coisas são o começo das dores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 9, 'Então vos entregarão para serdes afligidos, e vos matarão; e sereis odiados por todas as nações, por causa do meu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 10, 'E muitos tropeçarão na fé; e trairão uns aos outros, e uns aos outros se odiarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 11, 'E muitos falsos profetas se levantarão, e enganarão a muitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 12, 'E, por se multiplicar a injustiça, o amor de muitos se esfriará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 13, 'Mas o que perseverar até o fim, esse será salvo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 14, 'E este Evangelho do Reino será pregado em todo o mundo, como testemunho a todas as nações, e então virá o fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 15, 'Portanto, quando virdes que a abominação da desolação, dita pelo profeta Daniel, está no lugar santo, (quem lê, entenda),'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 16, 'então os que estiveram na Judeia fujam para os montes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 17, 'o que estiver no sobre o telhado não desça para tirar alguma coisa de sua casa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 18, 'e o que estiver no campo não volte atrás para tomar as suas roupas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 19, 'Mas ai das grávidas e das que amamentarem naqueles dias!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 20, 'Orai, porém, para que a vossa fuga não aconteça no inverno, nem no sábado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 21, 'Pois haverá então grande aflição, como nunca houve desde o princípio do mundo até agora, nem jamais haverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 22, 'E se aqueles dias não fossem encurtados, ninguém se salvaria; mas por causa dos escolhidos, aqueles dias serão encurtados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 23, 'Então, se alguém vos disser: “Olha o Cristo aqui”, ou “ [Olha ele] ali”, não creiais,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 24, 'pois se levantarão falsos cristos e falsos profetas; e farão tão grandes sinais e prodígios que, se fosse possível, enganariam até os escolhidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 25, 'Eis que eu tenho vos dito com antecedência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 26, 'Portanto, se vos disserem: “Eis que ele está no deserto”, não saiais; “Eis que ele está em um recinto”, não creiais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 27, 'Porque, assim como o relâmpago, que sai do oriente, e aparece até o ocidente, assim também será a vinda do Filho do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 28, 'Pois onde estiver o cadáver, ali se ajuntarão os abutres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 29, 'E logo depois da aflição daqueles dias, o sol se escurecerá, a lua não dará o seu brilho, as estrelas cairão do céu, e as forças dos céus se estremecerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 30, 'Então aparecerá no céu o sinal do Filho do homem. Naquela hora todas as tribos da terra lamentarão, e verão ao Filho do homem, que vem sobre as nuvens do céu, com poder e grande glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 31, 'E enviará os seus anjos com grande som de trombeta, e ajuntarão os seus escolhidos desde os quatro ventos, de uma extremidade à outra dos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 32, 'Aprendei a parábola da figueira: “Quando os seus ramos já ficam verdes, e as folhas brotam, sabeis que o verão [está] perto”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 33, 'Assim também vós, quando virdes todas estas coisas, sabei que já está perto, às portas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 34, 'Em verdade vos digo que esta geração não passará, até que todas estas coisas aconteçam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 35, 'O céu e a terra passarão, mas minhas palavras de maneira nenhuma passarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 36, 'Porém daquele dia e hora, ninguém sabe, nem os anjos do céu, a não ser meu Pai somente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 37, 'Assim como foram os dias de Noé, assim também será a vinda do Filho do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 38, 'Pois, assim como nos dias antes do dilúvio comiam, bebiam, casavam, e davam-se em casamento, até o dia em que Noé entrou na arca;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 39, 'e não sabiam, até que veio o dilúvio, e levou todos, assim também será a vinda do Filho do homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 40, 'Naquela hora dois estarão no campo; um será tomado, e o outro será deixado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 41, 'Duas estarão moendo em um moinho; uma será tomada, e a outra será deixada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 40, 'Mateus', 'Mt', 24, 42, 'Vigiai, pois, porque não sabeis em que hora o vosso Senhor virá.')
